begin;

select plan(40);

select has_column('public', 'personal_plan_portfolio_versions', 'parent_portfolio_version_id', 'successor portfolios retain their parent');
select has_column('public', 'personal_plan_portfolio_versions', 'lineage_product_draft_id', 'successor portfolios retain immutable draft lineage');
select has_function('public', 'personal_plan_stage_routine_source_successor', 'source successor RPC exists');
select has_function('public', 'personal_plan_claim_owner_routine_source_changes', 'owner-scoped source claim RPC exists');
select has_function('public', 'personal_plan_acquire_catalog_product_for_routine', 'atomic Routine acquisition RPC exists');
select ok(not has_function_privilege('authenticated', 'public.personal_plan_stage_routine_source_successor(uuid,uuid,uuid,bigint,bigint,text,text,integer,jsonb,integer,text,jsonb,text,jsonb,jsonb,text[],text)'::regprocedure, 'EXECUTE'), 'browser role cannot stage source successors');
select ok(not has_function_privilege('authenticated', 'public.personal_plan_claim_owner_routine_source_changes(uuid,uuid,integer,integer)'::regprocedure, 'EXECUTE'), 'browser role cannot claim owner source work');
select ok(has_function_privilege('service_role', 'public.personal_plan_stage_routine_source_successor(uuid,uuid,uuid,bigint,bigint,text,text,integer,jsonb,integer,text,jsonb,text,jsonb,jsonb,text[],text)'::regprocedure, 'EXECUTE'), 'service role can stage source successors');
select ok(not has_function_privilege('authenticated', 'public.personal_plan_acquire_catalog_product_for_routine(uuid,uuid,text,uuid)'::regprocedure, 'EXECUTE'), 'browser role cannot acquire Routine catalog products directly');
select ok(has_function_privilege('service_role', 'public.personal_plan_acquire_catalog_product_for_routine(uuid,uuid,text,uuid)'::regprocedure, 'EXECUTE'), 'service role can atomically acquire Routine catalog products');

insert into auth.users (instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
  ('00000000-0000-0000-0000-000000000000','12000000-0000-0000-0000-000000000001','authenticated','authenticated','source-a@example.invalid','',now(),'{}','{}',now(),now()),
  ('00000000-0000-0000-0000-000000000000','12000000-0000-0000-0000-000000000002','authenticated','authenticated','source-b@example.invalid','',now(),'{}','{}',now(),now());
insert into public.leads (id,name,email,marketing_consent,quiz_answers,quiz_kind,user_id) values
  ('12100000-0000-0000-0000-000000000001','','source-a@example.invalid',false,'{}','legacy','12000000-0000-0000-0000-000000000001'),
  ('12100000-0000-0000-0000-000000000002','','source-b@example.invalid',false,'{}','legacy','12000000-0000-0000-0000-000000000002');
insert into public.personal_plans (id,user_id) values
  ('22000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001'),
  ('22000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000002');
insert into public.personal_plan_need_versions (
  id,user_id,personal_plan_id,kind,parent_need_version_id,stage1_source_kind,
  stage1_source_lead_id,schema_version,computation_version,input_hash,input_snapshot,output_snapshot
) values
  ('32000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','initial',null,'legacy_quiz_lead','12100000-0000-0000-0000-000000000001',1,'test',repeat('1',64),'{}','{}'),
  ('32000000-0000-0000-0000-000000000003','12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','initial',null,'legacy_quiz_lead','12100000-0000-0000-0000-000000000002',1,'test',repeat('3',64),'{}','{}');
insert into public.personal_plan_need_versions (id,user_id,personal_plan_id,kind,parent_need_version_id,schema_version,computation_version,input_hash,input_snapshot,output_snapshot) values
  ('32000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','refined','32000000-0000-0000-0000-000000000001',1,'test',repeat('2',64),'{}','{}'),
  ('32000000-0000-0000-0000-000000000004','12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','refined','32000000-0000-0000-0000-000000000003',1,'test',repeat('4',64),'{}','{}');
update public.personal_plans set current_refined_need_version_id=case id when '22000000-0000-0000-0000-000000000001'::uuid then '32000000-0000-0000-0000-000000000002'::uuid else '32000000-0000-0000-0000-000000000004'::uuid end;
insert into public.personal_plan_product_drafts (id,user_id,personal_plan_id,refined_need_version_id,contract_version,revision,status) values
 ('42000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000002',1,1,'completed'),
 ('42000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','32000000-0000-0000-0000-000000000004',1,1,'completed');
insert into public.personal_plan_portfolio_versions (id,user_id,personal_plan_id,refined_need_version_id,source_product_draft_id,lineage_product_draft_id,source_product_draft_revision,schema_version,category_authority_versions,content_hash,snapshot) values
 ('52000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000002','42000000-0000-0000-0000-000000000001','42000000-0000-0000-0000-000000000001',1,1,'{}',repeat('5',64),'{}'),
 ('52000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','32000000-0000-0000-0000-000000000004','42000000-0000-0000-0000-000000000002','42000000-0000-0000-0000-000000000002',1,1,'{}',repeat('6',64),'{"ownedProducts":[{"userProductId":"82000000-0000-0000-0000-000000000099"}],"pendingProducts":[]}');
insert into public.personal_plan_routine_versions (id,user_id,personal_plan_id,source_refined_need_version_id,source_portfolio_version_id,source_product_draft_id,source_product_draft_revision,schema_version,compiler_version,authority_versions,source_fingerprint,payload_hash,payload) values
 ('61000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','32000000-0000-0000-0000-000000000002','52000000-0000-0000-0000-000000000001','42000000-0000-0000-0000-000000000001',1,1,'test','{}','active',repeat('7',64),'{}'),
 ('61000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','32000000-0000-0000-0000-000000000004','52000000-0000-0000-0000-000000000002','42000000-0000-0000-0000-000000000002',1,1,'test','{}','active',repeat('8',64),'{}');
update public.personal_plans set active_routine_version_id='61000000-0000-0000-0000-000000000001' where id='22000000-0000-0000-0000-000000000001';
do $setup$
begin
  perform public.personal_plan_enqueue_routine_source_change('12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','refined_need','32000000-0000-0000-0000-000000000004');
  perform public.personal_plan_enqueue_routine_source_change('12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','portfolio_version','52000000-0000-0000-0000-000000000002');
  perform public.personal_plan_enqueue_routine_source_change('12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','user_product','82000000-0000-0000-0000-000000000099');
  perform public.personal_plan_enqueue_routine_source_change('12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','refined_need','32000000-0000-0000-0000-000000000003');
end;
$setup$;
insert into public.personal_plan_routine_proposals (id,user_id,personal_plan_id,candidate_routine_version_id,origin,status,source_revision,source_fingerprint,proposal_fingerprint,delta) values
 ('71000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','61000000-0000-0000-0000-000000000002','stage3_completion','pending',(select source_revision from public.personal_plans where id='22000000-0000-0000-0000-000000000002'),'active',repeat('9',64),'{}');
update public.personal_plan_routine_source_change_outbox
   set status='processing',
       lease_token='92000000-0000-0000-0000-000000000099',
       lease_expires_at=now()+interval '60 seconds',
       last_error_code='unresolved_product_review'
 where personal_plan_id='22000000-0000-0000-0000-000000000002'
   and source_kind='user_product';
update public.personal_plans
   set pending_routine_proposal_id='71000000-0000-0000-0000-000000000002', revision=1
 where id='22000000-0000-0000-0000-000000000002';
select is(public.personal_plan_confirm_routine_proposal('12000000-0000-0000-0000-000000000002','22000000-0000-0000-0000-000000000002','71000000-0000-0000-0000-000000000002',1)->>'outcome','accepted','proposal acceptance drives exact refinement settlement');
select is((select active_routine_version_id::text from public.personal_plans where id='22000000-0000-0000-0000-000000000002'),'61000000-0000-0000-0000-000000000002','activation trigger preserves the accepted Routine pointer');
select is((select count(*)::integer from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000002' and source_kind='refined_need' and source_key='32000000-0000-0000-0000-000000000004' and available_at='infinity'::timestamptz and processed_revision=observed_revision),1,'activation settles the exact accepted refinement revision');
select is((select count(*)::integer from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000002' and source_kind='portfolio_version' and available_at<>'infinity'::timestamptz and processed_revision=0),1,'activation does not sweep portfolio work outside its owning completion transaction');
select is((select count(*)::integer from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000002' and source_kind='user_product' and status='processing' and lease_token='92000000-0000-0000-0000-000000000099' and last_error_code='unresolved_product_review'),1,'activation preserves a live deferred product-review lease and operator breadcrumb');
select is((select count(*)::integer from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000002' and source_key='32000000-0000-0000-0000-000000000003' and available_at<>'infinity'::timestamptz and processed_revision=0),1,'activation leaves an unrelated source key available');
insert into public.products (id,name,category,category_key,is_active,lifecycle_status,is_chaarlie_recommended) values ('72000000-0000-0000-0000-000000000001','Source contract conditioner','Conditioner','conditioner',true,'active',false);
insert into public.user_products (id,user_id,category,catalog_product_id,identity_status,ownership_status) values ('82000000-0000-0000-0000-000000000001','12000000-0000-0000-0000-000000000001','conditioner','72000000-0000-0000-0000-000000000001','matched','owned');

create function pg_temp.stage(p_snapshot jsonb default '{"schemaVersion":1,"personalPlanId":"22000000-0000-0000-0000-000000000001","refinedVersionId":"32000000-0000-0000-0000-000000000002","ownedProducts":[{"userProductId":"82000000-0000-0000-0000-000000000001","category":"conditioner","productId":"72000000-0000-0000-0000-000000000001"}],"pendingProducts":[],"plannedPurchases":[]}'::jsonb, p_revision bigint default null, p_source_revision bigint default null)
returns jsonb language sql as $$ select public.personal_plan_stage_routine_source_successor('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000001',coalesce(p_revision,(select revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001')),coalesce(p_source_revision,(select source_revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001')),'user_product','82000000-0000-0000-0000-000000000001',1,p_snapshot,1,'test','{}',repeat('a',64),'{"steps":["candidate"]}','{"changed":["source"]}',array['source'], 'source_sync') $$;

select is(pg_temp.stage()->>'outcome','staged','matched live owner product stages a pending successor');
select is((select active_routine_version_id::text from public.personal_plans where id='22000000-0000-0000-0000-000000000001'),'61000000-0000-0000-0000-000000000001','successor staging does not activate');
select is((select count(*)::integer from public.personal_plan_portfolio_versions where personal_plan_id='22000000-0000-0000-0000-000000000001'),2,'source event creates one immutable successor portfolio');
select is((select parent_portfolio_version_id::text from public.personal_plan_portfolio_versions where source_key='82000000-0000-0000-0000-000000000001'),'52000000-0000-0000-0000-000000000001','successor points to exact base portfolio');
select is((select r.payload#>>'{source,productPortfolioVersionId}' from public.personal_plan_routine_versions r join public.personal_plans p on p.pending_routine_proposal_id is not null join public.personal_plan_routine_proposals proposal on proposal.id=p.pending_routine_proposal_id and proposal.candidate_routine_version_id=r.id where p.id='22000000-0000-0000-0000-000000000001'),(select id::text from public.personal_plan_portfolio_versions where source_key='82000000-0000-0000-0000-000000000001'),'stored Routine payload contains exact successor portfolio ID');
select is(pg_temp.stage()->>'outcome','already_staged','same source event is idempotent');
select ok(public.personal_plan_enqueue_routine_source_change('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','user_product','82000000-0000-0000-0000-000000000001') > 0,'reused exact identity creates a fresh source revision even without a user-product field update');
select is((select observed_revision from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000001' and source_key='82000000-0000-0000-0000-000000000001'),(select source_revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001'),'reused identity coalesces onto its one durable source event rather than duplicating a successor');
insert into public.products (id,name,category,category_key,is_active,lifecycle_status,is_chaarlie_recommended) values ('72000000-0000-0000-0000-000000000002','Atomic acquisition conditioner','Conditioner','conditioner',true,'active',false);
with prior as materialized (select source_revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001'), acquired as materialized (select public.personal_plan_acquire_catalog_product_for_routine('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','conditioner','72000000-0000-0000-0000-000000000002') as result from prior) select is((result->>'sourceRevision')::bigint,prior.source_revision+1,'new catalog acquisition increments source revision exactly once') from prior, acquired;
with prior as materialized (select source_revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001'), acquired as materialized (select public.personal_plan_acquire_catalog_product_for_routine('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','conditioner','72000000-0000-0000-0000-000000000002') as result from prior) select is((result->>'sourceRevision')::bigint,prior.source_revision+1,'reused catalog acquisition increments source revision exactly once') from prior, acquired;
select is((select count(*)::integer from public.user_products where user_id='12000000-0000-0000-0000-000000000001' and catalog_product_id='72000000-0000-0000-0000-000000000002' and ownership_status='owned'),1,'repeated acquisition retains one exact user-product identity');
update public.personal_plan_routine_source_change_outbox set status='processing',lease_token='92000000-0000-0000-0000-000000000001',lease_expires_at=now()+interval '60 seconds' where personal_plan_id='22000000-0000-0000-0000-000000000001' and source_key=(select id::text from public.user_products where user_id='12000000-0000-0000-0000-000000000001' and catalog_product_id='72000000-0000-0000-0000-000000000002');
select ok(public.personal_plan_finish_routine_source_change((select id from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000001' and lease_token='92000000-0000-0000-0000-000000000001'),'92000000-0000-0000-0000-000000000001',(select observed_revision from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000001' and lease_token='92000000-0000-0000-0000-000000000001'),'terminal_invalid_source'),'terminal invalid source finishes its exact observed revision');
select is((select last_error_code from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000001' and source_key=(select id::text from public.user_products where user_id='12000000-0000-0000-0000-000000000001' and catalog_product_id='72000000-0000-0000-0000-000000000002')),'terminal_invalid_source','terminal source outcome remains visible for operators');
select is((select available_at from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000001' and source_key=(select id::text from public.user_products where user_id='12000000-0000-0000-0000-000000000001' and catalog_product_id='72000000-0000-0000-0000-000000000002')),'infinity'::timestamptz,'terminal current revision does not retry forever');
select ok(public.personal_plan_enqueue_routine_source_change('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','user_product',(select id::text from public.user_products where user_id='12000000-0000-0000-0000-000000000001' and catalog_product_id='72000000-0000-0000-0000-000000000002')) > (select processed_revision from public.personal_plan_routine_source_change_outbox where personal_plan_id='22000000-0000-0000-0000-000000000001' and source_key=(select id::text from public.user_products where user_id='12000000-0000-0000-0000-000000000001' and catalog_product_id='72000000-0000-0000-0000-000000000002')),'a later truthful source update reopens terminal work with a newer revision');
select is(pg_temp.stage('{"schemaVersion":1,"personalPlanId":"22000000-0000-0000-0000-000000000001","refinedVersionId":"32000000-0000-0000-0000-000000000002","ownedProducts":[],"pendingProducts":[],"plannedPurchases":[]}'::jsonb)->>'outcome','invalid_source','forged matched snapshot cannot create a portfolio');
select is((select count(*)::integer from public.personal_plan_portfolio_versions where personal_plan_id='22000000-0000-0000-0000-000000000001'),2,'invalid snapshot leaves immutable portfolio history unchanged');
insert into public.user_products (id,user_id,category,identity_status,ownership_status) values ('82000000-0000-0000-0000-000000000002','12000000-0000-0000-0000-000000000001','conditioner','pending_review','owned');
select is(public.personal_plan_stage_routine_source_successor('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000001','61000000-0000-0000-0000-000000000001',(select revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001'),(select source_revision from public.personal_plans where id='22000000-0000-0000-0000-000000000001'),'user_product','82000000-0000-0000-0000-000000000002',1,'{"schemaVersion":1,"personalPlanId":"22000000-0000-0000-0000-000000000001","refinedVersionId":"32000000-0000-0000-0000-000000000002","ownedProducts":[{"userProductId":"82000000-0000-0000-0000-000000000001","category":"conditioner","productId":"72000000-0000-0000-0000-000000000001"}],"pendingProducts":[{"userProductId":"82000000-0000-0000-0000-000000000002","category":"conditioner","submissionId":"missing-submission"}],"plannedPurchases":[]}',1,'test','{}','unresolved','{}','{}','{}','product_review')->>'outcome','invalid_source','unresolved product review without a live submission cannot be consumed as a successor');
select is((select count(*)::integer from public.personal_plan_portfolio_versions where personal_plan_id='22000000-0000-0000-0000-000000000001'),2,'unresolved product review leaves portfolio history unchanged for retry');
select is(pg_temp.stage(p_revision => 0, p_source_revision => 0)->>'outcome','revision_conflict','stale revision rejected');
select is(public.personal_plan_stage_routine_source_successor('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000002','61000000-0000-0000-0000-000000000002',0,0,'user_product','82000000-0000-0000-0000-000000000001',1,'{}',1,'test','{}','x','{}','{}','{}','source_sync')->>'outcome','invalid_source','foreign owner or plan is rejected');
select is((select count(*)::integer from public.personal_plan_claim_owner_routine_source_changes('12000000-0000-0000-0000-000000000001','22000000-0000-0000-0000-000000000002',20,30)),0,'owner-scoped claim never claims a foreign plan');
set role service_role;
select throws_ok($$update public.personal_plan_portfolio_versions set snapshot='{}' where id='52000000-0000-0000-0000-000000000001'$$,'22000','personal plan version rows are immutable','successor portfolio lineage remains immutable');
select throws_ok($$delete from public.personal_plan_portfolio_versions where id='52000000-0000-0000-0000-000000000001'$$,'22000','personal plan version rows are immutable','service role cannot delete immutable portfolios');
reset role;

select * from finish();
rollback;
